// @ts-check
// Instance export. The plugin decides what goes in the archive; the launcher asks where to save and writes it.
/** @typedef {import("../packages/plugin-api").TN} TN */
/** @typedef {import("../packages/plugin-api").Instance} Instance */
/** @typedef {import("../packages/plugin-api").ContentKind} ContentKind */
/** @typedef {import("../packages/plugin-api").ExportSpec} ExportSpec */

/** Never worth sharing: regenerated by the game. */
const JUNK = ["logs", "crash-reports", ".cache"];
const DIRS = /** @type {Record<ContentKind, string>} */ ({ mod: "mods", resourcepack: "resourcepacks", shader: "shaderpacks" });
const MRPACK_LOADER = /** @type {Record<string, string>} */ ({ fabric: "fabric-loader", quilt: "quilt-loader", forge: "forge", neoforge: "neoforge" });
const PRISM_LOADER = /** @type {Record<string, string>} */ ({
  fabric: "net.fabricmc.fabric-loader",
  quilt: "org.quiltmc.quilt-loader",
  forge: "net.minecraftforge",
  neoforge: "net.neoforged",
  liteloader: "com.mumfrey.liteloader",
});

/** @typedef {{ path: string; sha1: string; sha512: string; url: string; size: number }} Hosted */

/**
 * `modrinth.index.json`: hosted files are downloaded on import, everything else rides in `overrides/`.
 * @param {Pick<Instance, "name" | "version" | "loader" | "loaderVersion">} inst @param {Hosted[]} hosted
 */
export function mrpackIndex(inst, hosted) {
  const loader = MRPACK_LOADER[inst.loader];
  if (inst.loader !== "vanilla" && !loader) throw new Error(`Modrinth packs do not support ${inst.loader}`);
  return {
    formatVersion: 1,
    game: "minecraft",
    versionId: "1.0.0",
    name: inst.name,
    files: hosted.map((f) => ({ path: f.path, hashes: { sha1: f.sha1, sha512: f.sha512 }, downloads: [f.url], fileSize: f.size })),
    dependencies: { minecraft: inst.version, ...(loader ? { [loader]: inst.loaderVersion } : {}) },
  };
}

/** `instance.cfg` and `mmc-pack.json` of a Prism/MultiMC instance. @param {Pick<Instance, "name" | "version" | "loader" | "loaderVersion">} inst */
export function prismFiles(inst) {
  const components = [{ uid: "net.minecraft", version: inst.version, important: true }];
  if (inst.loader !== "vanilla") components.push({ uid: PRISM_LOADER[inst.loader], version: inst.loaderVersion, important: false });
  return {
    "instance.cfg": `InstanceType=OneSix\nname=${inst.name.replace(/\n/g, " ")}\n`,
    "mmc-pack.json": JSON.stringify({ formatVersion: 1, components }, null, 2),
  };
}

/** Files of the instance Modrinth hosts, found by SHA-1; disabled ones are left out. @param {TN} tn @param {string} id */
async function hostedFiles(tn, id) {
  /** @type {Map<string, string>} sha1 -> instance path */
  const bySha1 = new Map();
  /** @type {string[]} */
  const disabled = [];
  for (const kind of /** @type {ContentKind[]} */ (Object.keys(DIRS))) {
    for (const [file, sha1] of Object.entries(await tn.content.hashes(id, kind))) {
      if (file.endsWith(".disabled")) disabled.push(`${DIRS[kind]}/${file}`);
      else bySha1.set(sha1, `${DIRS[kind]}/${file}`);
    }
  }
  /** @type {Hosted[]} */
  const hosted = [];
  if (bySha1.size) {
    const res = await tn.net.fetch("https://api.modrinth.com/v2/version_files", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ hashes: [...bySha1.keys()], algorithm: "sha1" }),
    });
    if (!res.ok) throw new Error(`Modrinth answered HTTP ${res.status}`);
    for (const [sha1, version] of Object.entries(/** @type {Record<string, any>} */ (res.json()))) {
      const f = version.files.find((/** @type {any} */ f) => f.hashes.sha1 === sha1);
      if (f) hosted.push({ path: /** @type {string} */ (bySha1.get(sha1)), sha1, sha512: f.hashes.sha512, url: f.url, size: f.size });
    }
  }
  return { hosted, disabled };
}

/**
 * Asks where to save and exports; resolves with the saved path, or null when the user cancels.
 * @param {TN} tn @param {string} id @param {{ format: "mrpack" | "prism"; worlds: boolean }} o
 */
export async function exportInstance(tn, id, o) {
  const inst = await tn.instances.get(id);
  const skip = [...JUNK, ...(o.worlds ? [] : ["saves"])];
  /** @type {ExportSpec} */
  let spec;
  if (o.format === "mrpack") {
    const { hosted, disabled } = await hostedFiles(tn, id);
    spec = {
      fileName: `${inst.name}.mrpack`,
      root: "overrides",
      files: { "modrinth.index.json": JSON.stringify(mrpackIndex(inst, hosted), null, 2) },
      skip: [...skip, ...disabled, ...hosted.map((f) => f.path)],
    };
  } else {
    spec = { fileName: `${inst.name}.zip`, root: ".minecraft", files: prismFiles(inst), skip };
  }
  return tn.instances.export(id, spec);
}

export function activate() {}
